<?php
ini_set('display_errors',0); error_reporting(E_ALL); require_once __DIR__ . '/config.php'; header('Content-Type: application/json; charset=utf-8');
function sb($m,$ep,$p=null){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CUSTOMREQUEST=>$m,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json','Prefer: return=representation'],CURLOPT_TIMEOUT=>60]);if($p!==null)curl_setopt($ch,CURLOPT_POSTFIELDS,json_encode($p));$b=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ['ok'=>$http>=200&&$http<300,'http'=>$http,'body'=>$b,'data'=>is_array($d)?$d:[]];}
try{$key=$_GET['key']??'';if(!defined('AFTER_HOURS_CRON_KEY')||!hash_equals(AFTER_HOURS_CRON_KEY,$key)){http_response_code(403);echo json_encode(['success'=>false,'error'=>'Invalid key']);exit;}
$rows=sb('GET','municipal_owner_records?select=*&order=updated_at.desc&limit=2000');if(!$rows['ok']){echo json_encode(['success'=>false,'error'=>'Could not read municipal_owner_records','details'=>$rows['body']],JSON_PRETTY_PRINT);exit;}
$scored=0;$top=[];foreach($rows['data'] as $r){$score=35;$tenure=(int)($r['estimated_tenure_years']??0);$tax=(float)($r['total_tax']??0);$out=(float)($r['outstanding']??0);$owner=strtoupper($r['owner_name']??'');if($tenure>=7)$score+=20;if($tenure>=12)$score+=10;if($tax>=15000)$score+=10;if($tax>=25000)$score+=10;if($out>0)$score+=5;if(str_contains($owner,'LLC')||str_contains($owner,'TRUST')||str_contains($owner,'ESTATE'))$score+=8;if(($r['dnc_status']??'not_checked')==='clear')$score+=5;if(($r['realtor_status']??'not_checked')==='clear')$score+=5;$score=min(100,$score);$status=$score>=90?'mark_review':($score>=80?'priority_research':'research');sb('PATCH','municipal_owner_records?id=eq.'.rawurlencode($r['id']),['owner_signal_score'=>$score,'priority_status'=>$status,'notes'=>'Scored by Jessica: tenure '.$tenure.' years, tax $'.number_format($tax).', outstanding $'.number_format($out).'. DNC/realtor exclusion required before outreach.','updated_at'=>date('c')]);$scored++;if($score>=80)$top[]=['owner_name'=>$r['owner_name'],'property_address'=>$r['property_address'],'town'=>$r['town'],'score'=>$score,'tenure'=>$tenure,'total_tax'=>$tax,'status'=>$status];}
usort($top,fn($a,$b)=>$b['score']<=>$a['score']);echo json_encode(['success'=>true,'records_scored'=>$scored,'top_priority'=>array_slice($top,0,25),'compliance_note'=>'Use public-record data for research/segmentation. Run DNC, realtor exclusion, and human approval before any direct outreach.'],JSON_PRETTY_PRINT);}
catch(Throwable $e){http_response_code(500);echo json_encode(['success'=>false,'error'=>$e->getMessage(),'line'=>$e->getLine()],JSON_PRETTY_PRINT);}
?>